import java.util.*;

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> res = new ArrayList<>();
        int L = words[0].length(), m = words.length, n = s.length();
        if ((long) L * m > n) return res;
        Map<String, Integer> need = new HashMap<>();
        for (String w : words) need.merge(w, 1, Integer::sum);
        for (int o = 0; o < L; o++) {                    // each way of cutting s into L-chunks
            Map<String, Integer> have = new HashMap<>();
            int left = o, used = 0;
            for (int right = o; right + L <= n; right += L) {
                String w = s.substring(right, right + L);
                if (!need.containsKey(w)) {              // a chunk that is not a word: restart after it
                    have.clear(); used = 0; left = right + L;
                    continue;
                }
                have.merge(w, 1, Integer::sum); used++;
                while (have.get(w) > need.get(w)) {      // too many copies of w: drop from the left
                    String lw = s.substring(left, left + L);
                    have.merge(lw, -1, Integer::sum); used--; left += L;
                }
                if (used == m) {                         // window holds exactly the word list
                    res.add(left);
                    String lw = s.substring(left, left + L);
                    have.merge(lw, -1, Integer::sum); used--; left += L;
                }
            }
        }
        Collections.sort(res);
        return res;
    }
}

