class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        L = len(words[0]); m = len(words); need = Counter(words); out = []
        for off in range(L):
            l = off; win = Counter(); used = 0
            for r in range(off, len(s) - L + 1, L):
                w = s[r:r + L]
                if w not in need:
                    win.clear(); used = 0; l = r + L; continue
                win[w] += 1; used += 1
                while win[w] > need[w]:
                    win[s[l:l + L]] -= 1; used -= 1; l += L
                if used == m: out.append(l)
        return sorted(out)

