function findSubstring(s, words) {
  const L = words[0].length, m = words.length, need = new Map(), out = [];
  for (const w of words) need.set(w, (need.get(w) || 0) + 1);
  for (let off = 0; off < L; off++) {
    let l = off, used = 0; const win = new Map();
    for (let r = off; r + L <= s.length; r += L) {
      const w = s.slice(r, r + L);
      if (!need.has(w)) { win.clear(); used = 0; l = r + L; continue; }
      win.set(w, (win.get(w) || 0) + 1); used++;
      while (win.get(w) > need.get(w)) { const x = s.slice(l, l + L); win.set(x, win.get(x) - 1); used--; l += L; }
      if (used === m) out.push(l);
    }
  }
  return out.sort((a, b) => a - b);
}
